    ax.add_patch(FancyBboxPatch((cx - w / 2, alt), w, ust - alt, boxstyle="round,pad=0,rounding_size=0.12",
                                fc='#e2e8f0', ec='#0f172a', linewidth=2.2, zorder=2))
    px0, px1 = cx - w / 2 + 0.09, cx + w / 2 - 0.09
