def _on_topic(q, topics, subject=None, grade_label=None):
    """Soru, seçilen konu/ünite metnine uygun mu? Emin olmadığında True (gereksiz eleme yapmaz)."""
    try:
        tl = str(topics or "").replace("İ", "i").replace("I", "ı").lower()
        if not tl.strip():
            return True
        subj = subject or q.get("subject")
        if grade_label and not _unit_guard(q, topics, subj, grade_label):
            return False
        body = " ".join(str(x) for x in (q.get("topic", ""), q.get("question", ""), q.get("passage", ""), " ".join(str(v) for v in (q.get("options") or {}).values()))).lower()
        groups = _TOPIC_GROUPS.get(subj)
        if groups:
            sel = [(n, c) for n, trig, c in groups if re.search(trig, tl)]
            if sel:
                if subj == "Matematik":
                    names = {n for n, _c in sel}
                    hits = {g for g, rx in _MAT_STRONG.items() if re.search(rx, body)}
                    foreign = hits - names
                    if "olasılık" in names:
                        foreign.discard("kesir")  # olasılık cevapları kesirle yazılır (1/2 gibi)
                    if foreign and (not (hits & names) or foreign & {"kesir", "olasılık", "sayi", "veri"}):
                        return False  # başka ünitenin güçlü imzası var
                    if not (names & {"geo_sekil", "geo_nicelik"}):
                        shp = q.get("shape")
                        if isinstance(shp, dict) and str(shp.get("type", "")).lower() in ("geo", "triangle", "circle", "rectangle"):
                            return False  # geometri şekli yalnızca geometri konularında
                    req = [(n, c) for n, c in sel if c is not None]
                    if len(req) < len(sel):
                        return True  # 'sayı/işlem' gibi geniş ünite: yalnızca dışlama kuralı
                    sel = req
                return any(re.search(r"(?<![a-zçğıöşü])(?:" + c + ")", body) for _n, c in sel)
        if subj in ("Sosyal Bilgiler", "Din Kültürü ve Ahlak Bilgisi"):
            want = _pool_tok(tl)
            qt = str(q.get("topic") or "")
            if want and qt.strip() and not (want & _pool_tok(qt)) and not (want & _pool_tok(body)):
                return False
        return True
    except Exception:
        return True


# ---------------------------------------------------------------- ÜNİTE SINIFLAYICI: soru hangi üniteye ait? (müfredat metninden, IDF ağırlıklı)
_UNIT_GENERIC = frozenset(w[:5] for w in (
    "yorumlayabilme çıkarım ilişkin yönelik kullanabilme yansıtabilme çözebilme değerlendirebilme temsil gerçek yaşam durumlarına karşılık "
    "farklı biçimlerde ifade edilen gösterimlerle yapabilme muhakeme günlük hayat matematiksel durumlarda problemleri problem deneyimlerini "
    "araç teknolojiyi teknoloji bilgi becerileri özellikleri özellik açıklayabilme belirleyebilme karşılaştırabilme sınıflandırabilme "
    "uzunluk toplam ilgili örnekler örnek verilen aşağıdaki hangisi hangisidir göre kaçtır olduğuna şekilde şekildeki tabloda bunlardan "
    "doğru doğrudur yanlış ünite ünitesi ünitesine ünitesiyle bilgi bilgiler bilgidir bilgilerden konu konusu konusunda ifade ifadelerden").split())
_UM = {}


def _unit_tokens(text):
    t = str(text or "").replace("İ", "i").replace("I", "ı").lower().replace("’", "").replace("'", "")  # Kur'an / Kur’an aynı sözcük
    return {w[:5] for w in re.findall(r"[a-zçğıöşü]{4,}", t)} - _UNIT_GENERIC


def _unit_model(grade_label, subject):
    gl = str(grade_label or "")
    g = "LGS" if "LGS" in gl.upper() else next((c for c in gl if c.isdigit()), "")
    key = (g, subject)
    if key in _UM:
        return _UM[key]
    m = None
    try:
        from . import curriculum as _cu
        us = [(n, [str(x) for x in t]) for n, t in _cu.units(g, subject)]
        if len(us) >= 2:
            toks = [_unit_tokens(n + " " + " ".join(t)) for n, t in us]
            df = {}
            for ts in toks:
                for w in ts:
                    df[w] = df.get(w, 0) + 1
            import math as _m
            idf = {w: _m.log(len(us) / c) for w, c in df.items()}
            m = (us, toks, idf)
    except Exception:
        m = None
    _UM[key] = m
    return m


def _selected_units(grade_label, subject, topics):
    """Plandaki 'topics' metninden seçilen ünitelerin adları (bulunamazsa None)."""
    m = _unit_model(grade_label, subject)
    if not m or not str(topics or "").strip():
        return None
    us = m[0]
    tp = str(topics)
    sel = {n for n, t in us if n and n in tp}
    if not sel:
        for n, t in us:
            if any(re.match(r"[A-ZÇĞİÖŞÜ]{2,4}\.\d+\.\d+\.\d+\.", k) and k.split(" ")[0] in tp for k in t):
                sel.add(n)
    if not sel:  # kazanım/alt konu metinlerinden bul
        for n, t in us:
            if any(len(k) >= 12 and k[:40] in tp for k in t):
                sel.add(n)
    return sel or None


def _unit_guard(q, topics, subject, grade_label):
    """False -> soru başka bir üniteye ait (kesin). Emin değilse True."""
    try:
        if subject not in ("Matematik", "Fen Bilimleri", "Sosyal Bilgiler", "Din Kültürü ve Ahlak Bilgisi") or not grade_label:
            return True
        m = _unit_model(grade_label, subject)
        sel = _selected_units(grade_label, subject, topics)
        if not m or not sel:
            return True
        us, toks, idf = m
        _qt = str(q.get("topic") or "").strip().lower()
        if _qt and any(_qt == str(n).split(" (")[0].strip().lower() for n in sel):
            return True  # banka sorusu kendi ünite adını taşıyor: şıklardaki çeldirici ifadeler başka üniteyi çağrıştırsa da ünite doğru
        T = _unit_tokens(f"{q.get('topic', '')} {q.get('kazanim', '')} {q.get('question', '')} {q.get('passage', '')}")
        if not T:
            return True
        sc = [sum(idf.get(w, 0.0) for w in (T & ts)) for ts in toks]
        best = max(range(len(us)), key=lambda i: sc[i])
        if us[best][0] in sel:
            return True
        mine = max((sc[i] for i, (n, _t) in enumerate(us) if n in sel), default=0.0)
        return not (sc[best] >= 1.2 and sc[best] > 1.3 * mine)
    except Exception:
        return True


def _kw_hit(tl, k):
    """Konu anahtar sözcüğü: kısa sözcükler (ay, ısı...) yalnızca tam sözcük olarak eşleşir; 'ayrıca' içindeki 'ay' sayılmaz."""
    if len(k) <= 3:
        return re.search(r"(?<![a-zçğıöşü])" + re.escape(k) + r"(?![a-zçğıöşü])", tl) is not None
    return re.search(r"(?<![a-zçğıöşü])" + re.escape(k), tl) is not None


def _mf_nest(subject):
    """5. sınıf: iç içe çemberler (ortak merkezli / yan yana eş / içten teğet). Metindeki her değer şekilde yazılıdır."""
    kind = random.choice(["gap", "outer_d", "chain", "inner", "ring3"])
    if kind == "gap":
        r1 = random.randint(2, 6)
        r2 = r1 + random.randint(2, 6)
        c = r2 - r1
        q = f"Şekilde O merkezli iç içe iki çemberin yarıçapları verilmiştir. İki çember arasındaki uzaklık (halkanın genişliği) kaç cm’dir?"
        sh = {"type": "geo", "sub_type": "nested_circles", "mode": "concentric", "radii": [r1, r2], "labels": [f"{r1} cm", f"{r2} cm"]}
        wr = [r1 + r2, r2 * 2 - r1, r1, c + 1, r2]
        ex = f"Halka genişliği = büyük yarıçap − küçük yarıçap = {r2} − {r1} = {c} cm."
        o = _mf_opts(c, wr, lambda v: f"{v} cm")
    elif kind == "outer_d":
        r1 = random.randint(2, 5)
        w = random.randint(2, 4)
        r2 = r1 + w
        c = 2 * r2
        q = f"Şekilde O merkezli iç içe iki çemberde küçük çemberin yarıçapı {r1} cm, iki çember arasındaki uzaklık {w} cm’dir. Büyük çemberin çapı kaç cm’dir?"
        sh = {"type": "geo", "sub_type": "nested_circles", "mode": "concentric", "radii": [r1, r2], "labels": [f"{r1} cm", ""], "bands": [f"{w} cm"]}
        wr = [r2, r1 + 2 * w, 2 * r1 + w, r1 + w + 2, c + 2]
        ex = f"Büyük yarıçap = {r1} + {w} = {r2} cm; çap = 2 × {r2} = {c} cm."
        o = _mf_opts(c, wr, lambda v: f"{v} cm")
    elif kind == "ring3":
        r1 = random.randint(1, 3)
        w1, w2 = random.randint(1, 3), random.randint(1, 3)
        r2, r3 = r1 + w1, r1 + w1 + w2
        c = 2 * r3
        q = (f"Şekilde O merkezli üç çemberin en küçüğünün yarıçapı {r1} cm’dir. Küçük ile orta çember arası {w1} cm, orta ile büyük çember arası {w2} cm’dir. "
             "Büyük çemberin çapı kaç cm’dir?")
        sh = {"type": "geo", "sub_type": "nested_circles", "mode": "concentric", "radii": [r1, r2, r3], "labels": [f"{r1} cm", "", ""], "bands": [f"{w1} cm", f"{w2} cm"]}
        wr = [r3, r1 + w1 + w2 + r1, 2 * (w1 + w2), c + 2, c - 2]
        ex = f"Büyük yarıçap = {r1} + {w1} + {w2} = {r3} cm; çap = 2 × {r3} = {c} cm."
        o = _mf_opts(c, wr, lambda v: f"{v} cm")
    elif kind == "chain":
        n = random.choice([3, 4, 5])
        r = random.randint(2, 6)
        c = 2 * r * n
        q = f"Şekilde birbirine teğet {n} eş çember yan yana dizilmiştir. Her bir çemberin yarıçapı {r} cm olduğuna göre dizinin toplam uzunluğu kaç cm’dir?"
        sh = {"type": "geo", "sub_type": "nested_circles", "mode": "chain", "n": n, "labels": [f"r = {r} cm", "?"]}
        wr = [r * n, 2 * r * (n - 1), r * (n + 1), c + r, c - r]
        ex = f"Her çemberin çapı 2 × {r} = {2 * r} cm; {n} çember: {n} × {2 * r} = {c} cm."
        o = _mf_opts(c, wr, lambda v: f"{v} cm")
    else:
        k = random.randint(2, 6)
        D = 4 * k
        c = k
        q = (f"Şekildeki büyük çemberin çapı {D} cm’dir. Küçük çemberin çapı büyük çemberin yarıçapına eşit ve küçük çember O merkezinden geçtiğine göre küçük çemberin yarıçapı kaç cm’dir?")
        sh = {"type": "geo", "sub_type": "nested_circles", "mode": "inner_tangent", "labels": [f"Çap = {D} cm"]}
        wr = [2 * k, D // 2, D, 3 * k, k + 1, k * 4 + 2]
        ex = f"Büyük çemberin yarıçapı {D}/2 = {2 * k} cm; küçük çemberin çapı {2 * k} cm, yarıçapı {2 * k}/2 = {k} cm."
        o = _mf_opts(c, wr, lambda v: f"{v} cm")
    return _mf_raw(subject, "Çember", q, o, ex, shape=sh) if o else None


