# ---------------------------------------------------------------- SOSYAL BİLGİLER: kodla hesaplanan veri soruları (5. sınıf)
def _sf_budget(subject):
    inc = random.choice([(120, 30), (150, 50), (200, 40), (180, 20)])
    items = random.sample([("Kırtasiye", 25), ("Kitap", 40), ("Yiyecek", 35), ("Ulaşım", 20), ("Oyuncak", 30), ("Sinema", 15)], 3)
    gelir, gider = inc[0] + inc[1], sum(v for _, v in items)
    if gider >= gelir:
        return None
    save = gelir - gider
    rows = [["Harçlık (gelir)", str(inc[0])], ["Ek gelir", str(inc[1])]] + [[n + " (gider)", str(v)] for n, v in items]
    shape = {"type": "table", "title": "Bir öğrencinin aylık bütçesi (TL)", "headers": ["Kalem", "Tutar (TL)"], "rows": rows}
    lead = "Bir öğrenci aylık gelirlerini ve giderlerini tabloda gösterildiği gibi kaydetmiştir."
    q = "Bu öğrenci ay sonunda tüm giderlerini yaptıktan sonra kaç TL tasarruf edebilmiştir?"
    o = _mf_opts(save, [gelir, gider, inc[0] - gider if inc[0] - gider != save else save + 10, save + 10], lambda v: f"{v} TL")
    return _mf_raw(subject, "Bütçe ve tasarruf", q, o, f"Gelir: {inc[0]} + {inc[1]} = {gelir} TL; gider: {gider} TL; tasarruf: {gelir} − {gider} = {save} TL.", shape=shape, passage=lead) if o else None


def _sf_rain(subject):
    ms = random.choice([["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran"], ["Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"]])
    vals = random.sample(range(10, 130, 10), 6)
    srt = sorted(zip(ms, vals), key=lambda x: -x[1])
    top2 = srt[0][1] + srt[1][1]
    tot = sum(vals)
    shape = {"type": "bar_chart", "title": "Bir şehrin aylık yağış miktarı (mm)", "labels": ms, "values": vals}
    lead = "Bir şehirde altı ay boyunca ölçülen aylık yağış miktarları grafikte verilmiştir."
    if random.random() < .5:
        q = "Grafiğe göre en çok yağış alan iki ayda düşen toplam yağış kaç mm'dir?"
        o = _mf_opts(top2, [srt[0][1] + srt[2][1], srt[0][1], tot - top2, top2 + 10], lambda v: f"{v} mm")
        ex = f"En çok yağış: {srt[0][0]} ({srt[0][1]}) ve {srt[1][0]} ({srt[1][1]}) → {top2} mm."
    else:
        d = srt[0][1] - srt[-1][1]
        q = "Grafiğe göre en çok yağış alan ay ile en az yağış alan ay arasındaki yağış farkı kaç mm'dir?"
        o = _mf_opts(d, [d + 10, d - 10 if d > 10 else d + 20, srt[0][1], tot], lambda v: f"{v} mm")
        ex = f"{srt[0][1]} − {srt[-1][1]} = {d} mm."
    return _mf_raw(subject, "Yağış ve iklim", q, o, ex, shape=shape, passage=lead) if o else None


_SF_GENS = [(_sf_budget, ("ekonomi", "bütçe", "tasarruf", "ihtiyaç", "gelir")), (_sf_rain, ("iklim", "yağış", "harita", "hava durumu"))]


def sosyal_questions(grade_label, n, topics="", seen=(), dl=0):
    """5. sınıf Sosyal için cevabı kodla hesaplanan, görselli sorular."""
    gl = str(grade_label or "")
    if n <= 0 or "5" not in gl[:2]:
        return []
    tl = str(topics or "").replace("İ", "i").replace("I", "ı").lower()
    sel = [f for f, kw in _SF_GENS if any(_kw_hit(tl, k) for k in kw)]
    if not sel:
        return []
    out, stems = [], set(seen)
    rkey = ("gen", "Sosyal Bilgiler", "5")
    byname = {f.__name__: f for f in sel if f.__name__ not in _bad_tpl_set()}
    byname = _item_scope(byname, "Sosyal Bilgiler", grade_label, topics)
    byname = _dl_filter(byname, dl, "Sosyal Bilgiler", grade_label, topics)
    for nm in _bal_order(rkey, byname, "Sosyal Bilgiler", grade_label, topics, n):
        if len(out) >= n:
            break
        for _t in range(4):
            try:
                raw = byname[nm]("Sosyal Bilgiler")
                x = _norm_q(raw, "Sosyal Bilgiler") if raw else None
            except Exception:
                x = None
            if x and _stem(x) not in stems:
                stems.add(_stem(x))
                x["vfd"] = True
                x["local"] = True
                x["tpl"] = nm
                _recent_mark(rkey, nm)
                out.append(x)
                break
    return out


def fen_questions(grade_label, n, topics="", seen=(), dl=0):
    """5. sınıf Fen 'Ay'ın hareketleri ve evreleri' için cevabı kodla hesaplanan sorular."""
    gl = str(grade_label or "")
    if n <= 0 or "5" not in gl[:2]:
        return []
    g_key = "5"
    tl = str(topics or "").replace("İ", "i").replace("I", "ı").lower()
    sel = [f for f, kw in _FF_GENS if any(_kw_hit(tl, k) for k in kw)]
    if not sel:
        return []
    out, stems = [], set(seen)
    rkey = ("gen", "Fen Bilimleri", g_key)
    byname = {f.__name__: f for f in sel if f.__name__ not in _bad_tpl_set()}
    byname = _item_scope(byname, "Fen Bilimleri", grade_label, topics)
    byname = _dl_filter(byname, dl, "Fen Bilimleri", grade_label, topics)
    for _pass in range(2):  # her kalıptan sınav başına en çok 1 soru (2. tur yalnızca eksik kalırsa)
        for nm in _bal_order(rkey, byname, "Fen Bilimleri", grade_label, topics, n):
            if len(out) >= n:
                break
            if _pass == 0 and any(x.get("tpl") == nm for x in out):
                continue
            for _t in range(4):
                try:
                    raw = byname[nm]("Fen Bilimleri")
                    x = _norm_q(raw, "Fen Bilimleri") if raw else None
                except Exception:
                    x = None
                if x and not _on_topic(x, topics, "Fen Bilimleri", grade_label):
                    x = None
                if x and _stem(x) not in stems:
                    stems.add(_stem(x))
                    x["vfd"] = True
                    x["local"] = True
                    x["tpl"] = nm
                    _recent_mark(rkey, nm)
                    out.append(x)
                    break
        if len(out) >= n:
            break
    return out


# ---------------------------------------------------------------- 5. SINIF FEN / SOSYAL / TÜRKÇE: doğrulanmış bilgi tablolarından kodla kurulan sorular (tek doğru, olumlu kök)
def _fact_q(subject, topic, q, correct, wrongs, ex, passage=""):
    ws = []
    for w in wrongs:
        if w != correct and w not in ws:
            ws.append(w)
    random.shuffle(ws)
    if len(ws) < 3:
        return None
    allv = [correct] + ws[:3]
    random.shuffle(allv)
    return _mf_raw(subject, topic, q, (allv, correct), ex, passage=passage)


_OPAK = ["tahta kapı", "demir levha", "kalın karton", "tuğla", "taş", "alüminyum folyo", "kalın kumaş perde"]
_SAYDAM = ["temiz pencere camı", "berrak su", "şeffaf cam bardak", "şeffaf naylon poşet", "hava"]
_YARI = ["buzlu cam", "yağlı kâğıt", "aydınger kâğıdı", "buzlu cam şişe"]


def _ff_ortam(subject):
    kind = random.choice(["saydam", "yari", "opak"])
    ad = {"saydam": "saydam", "yari": "yarı saydam", "opak": "opak (donuk)"}[kind]
    grp = {"saydam": _SAYDAM, "yari": _YARI, "opak": _OPAK}
    c = random.choice(grp[kind])
    wr = [random.choice(grp[k]) for k in grp if k != kind] + random.sample([x for k in grp if k != kind for x in grp[k]], 2)
    return _fact_q(subject, "Işığın Yayılması", f"Işığın madde içinden geçişine göre aşağıdaki maddelerden hangisi {ad} bir maddedir?", c, wr,
                   {"saydam": "Saydam maddeler ışığın büyük bölümünü geçirir ve arkasındaki cisimler net görülür.",
                    "yari": "Yarı saydam maddeler ışığın bir bölümünü geçirir; arkadaki cisimler net görülmez.",
                    "opak": "Opak (donuk) maddeler ışığı geçirmez; arkasında tam gölge oluşur."}[kind] + f" {c} bu gruptadır.")


def _ff_iletken(subject):
    ilet = ["bakır tel", "demir çivi", "alüminyum folyo", "çelik kaşık", "gümüş yüzük"]
    yal = ["plastik kalem", "tahta çubuk", "lastik silgi", "cam bardak", "kuru kâğıt", "yün kazak"]
    if random.random() < .5:
        c = random.choice(ilet)
        return _fact_q(subject, "Elektrik", "Bir elektrik devresine bağlandığında akımı ileten madde aşağıdakilerden hangisidir?", c, random.sample(yal, 3),
                       f"Metaller elektrik akımını iletir; {c} metaldendir. Diğerleri yalıtkandır.")
    c = random.choice(yal)
    return _fact_q(subject, "Elektrik", "Aşağıdakilerden hangisi elektrik akımını iletmeyen (yalıtkan) bir maddedir?", c, random.sample(ilet, 3),
                   f"{c} yalıtkandır; diğer seçenekler metal olduğu için iletkendir.")


def _ff_devre(subject):
    fn = [("pil", "devreye elektrik enerjisi sağlamak"), ("anahtar", "devreyi açıp kapatmak"), ("ampul", "elektrik enerjisini ışık enerjisine dönüştürmek"),
          ("bağlantı kablosu", "elektrik akımını elemanlar arasında iletmek")]
