def _bad_tpl_set():
    try:
        from . import store
        return store.bad_tpls()
    except Exception:
        return set()


def _diff_level(difficulty):
    m = re.search(r"(\d)\.", str(difficulty or ""))
    return int(m.group(1)) if m else 0


def _meb_types(subject, lvl):
    """MEB'in yayımladığı LGS örnek soru kitapçıklarındaki soru tiplerine (yeni nesil/beceri temelli) göre kalıp rehberi."""
    T = {
        "Türkçe": "sözcükte/cümlede/paragrafta anlam; deyim-atasözü; ana fikir ve çıkarım; metin türü; görsel+yönerge/metin ilişkisi; öncüllü (I-II-III) yargı değerlendirme",
        "Matematik": "görsel/tablo/grafik okuyup işlem yapma; metinden denklem/problem kurma; çok adımlı günlük hayat problemi; öncüllü doğru yargıları bulma; veri yorumlama; şekil üzerinde işlem",
        "Fen Bilimleri": "deney düzeneği okuyup değişken belirleme; tablo/grafik analizi; görsel (şema/model) yorumlama; neden-sonuç çıkarımı; bir iki bilgi düzeyi soru",
        "Sosyal Bilgiler": "kısa kaynak metinden çıkarım; kavram-bağlam eşleştirme; harita/tablo/grafik yorumlama; öncüllü önerme değerlendirme; neden-sonuç",
        "T.C. İnkılap Tarihi ve Atatürkçülük": "kaynak metinden çıkarım; kavram bağlama; öncüllü önerme-şık eşleştirme; neden-sonuç",
        "Din Kültürü ve Ahlak Bilgisi": "ayet/hadis/kısa metin yorumlama; kavram bilgisi; durum-davranış ilişkisi; öncüllü (doğru sayısını bulma)",
        "İngilizce": "kelime bilgisi; kısa metin okuma-anlama; tablo/broşür/afiş okuma; görsel-metin eşleştirme; ana fikir",
    }
    t = T.get(subject)
    if not t:
        return ""
    dist = {1: "%70 kolay (tek adım, doğrudan kazanım), %30 orta", 2: "%50 kolay, %50 orta", 3: "%20 kolay, %60 orta, %20 zor (MEB'in dengeli dağılımı)",
            4: "%20 orta, %60 zor, %20 kolay", 5: "%70 zor (çok aşamalı muhakeme), %30 orta", 6: "%80 çok zor, %20 zor"}.get(lvl or 3, "")
    return (f"\n📘 MEB/LGS SORU TİPLERİ (bu dersin MEB örneklerinde görülen tipler, soruları bunlara DAĞIT ve her soruda farklı tip kullan): {t}.\n"
            f"Sınav içinde zorluk dağılımı yaklaşık: {dist}. Soru kökü açık ve tek anlamlı olsun; çeldiriciler tipik öğrenci yanılgılarından türesin; "
            "5. sınıf için dil sade, ama soru yapısı MEB/LGS gibi olsun (metin/görsel/tablo → çıkarım → işlem ya da yargı).\n")


# ---------------------------------------------------------------- 5. SINIF: KALAN ÜNİTELER (açı ilişkileri, çokgen, dikdörtgen; ısı, iskelet; kurum, ihtiyaç, afet; metin türü)
def _mf_ang_tum(subject, kind=None):
    kind = kind or random.choice(["tumler", "butunler", "tur"])
    if kind == "tur":
        d = random.choice([20, 35, 45, 60, 75, 90, 110, 120, 135, 150, 165])
        c = "Dar açı" if d < 90 else ("Dik açı" if d == 90 else "Geniş açı")
        sh = {"type": "geo", "sub_type": "angle", "degree": d, "rotation": random.choice([0, 10, 20]), "labels": ["O", "A", "B"], "angle_label": f"{d}°"}
        o = _mf_opts(c, [x for x in ["Dar açı", "Dik açı", "Geniş açı", "Doğru açı"] if x != c], str, sort=False)
        return _mf_raw(subject, "Açı türleri", "Şekilde ölçüsü verilen AOB açısının türü aşağıdakilerden hangisidir?", o, f"{d}° ölçülü açı: " + ("90°’den küçük → dar açı." if d < 90 else "90° → dik açı." if d == 90 else "90°’den büyük, 180°’den küçük → geniş açı."), shape=sh) if o else None
    if kind == "tumler":
        d = random.choice(range(10, 81, 5))
        c, base, nm = 90 - d, 90, "tümleri"
    else:
        d = random.choice(range(20, 161, 10))
        c, base, nm = 180 - d, 180, "bütünleri"
    sh = {"type": "geo", "sub_type": "angle", "degree": d, "rotation": random.choice([0, 10, 20]), "labels": ["O", "A", "B"], "angle_label": f"{d}°"}
    wr = [d, base - d + 10, base - d - 10, base + d, abs(base - 2 * d) or base]
    o = _mf_opts(c, [w for w in wr if w > 0], str)
    return _mf_raw(subject, "Açı ilişkileri", f"Şekilde ölçüsü verilen AOB açısının {nm} kaç derecedir?", o, f"{'Tümler' if base == 90 else 'Bütünler'} açıların toplamı {base}°’dir: {base} − {d} = {c}.", shape=sh) if o else None


def _mf_ang_kom(subject, ters=None):
    d = random.choice(range(30, 151, 10))
    if d == 90:
        return None
    c = 180 - d
    sh = {"type": "geo", "sub_type": "angles_two_lines", "degree": d, "given": f"{d}°", "ask": "x"}
    o = _mf_opts(c, [d, c + 10, c - 10, 90 - d if d < 90 else d - 90, 360 - d], str)
    if (random.random() < .5) if ters is None else ters:  # ters (karşıt) açı: x açısının ters açısı x'e eşittir
        return _mf_raw(subject, "Açı ilişkileri", f"Şekilde kesişen iki doğrunun oluşturduğu açılardan biri {d}° olarak verilmiştir. Komşu açısı x ile gösterilen bu iki doğrunun oluşturduğu, x açısının ters (karşıt) açısı kaç derecedir?", o,
                       f"Komşu açılar bütünlerdir: x = 180 − {d} = {c}. Ters açılar eşittir; x’in ters açısı da {c}°’dir.", shape=sh) if o else None
    return _mf_raw(subject, "Açı ilişkileri", f"Şekilde kesişen iki doğrunun oluşturduğu açılardan biri {d}° olarak verilmiştir. Bu açının komşusu olan x açısı kaç derecedir?", o,
                   f"Komşu açılar bütünlerdir: 180 − {d} = {c}.", shape=sh) if o else None


def _mf_poly_el(subject):
    n = random.choice([3, 4, 5, 6, 7, 8])
    names = {3: "Üçgen", 4: "Dörtgen", 5: "Beşgen", 6: "Altıgen", 7: "Yedigen", 8: "Sekizgen"}
    sh = {"type": "geo", "sub_type": "polygon", "sides": n, "labels": list("ABCDEFGH")[:n], "equal_ticks": True}
    if random.random() < .5:
        c = names[n]
        o = _mf_opts(c, [v for k, v in names.items() if k != n], str, sort=False)
        return _mf_raw(subject, "Çokgenler", "Şekilde köşeleri harflerle gösterilen çokgenin adı aşağıdakilerden hangisidir?", o, f"Şekilde {n} kenar ve {n} köşe vardır; {n} kenarlı çokgen {c.lower()}dir.".replace("üçgendir", "üçgendir"), shape=sh) if o else None
    c = 2 * n
    o = _mf_opts(c, [n, n + 2, 3 * n, c - 1, c + 1], str)
    return _mf_raw(subject, "Çokgenler", "Şekildeki çokgenin kenar sayısı ile köşe sayısının toplamı kaçtır?", o, f"Bir çokgenin kenar sayısı köşe sayısına eşittir: {n} + {n} = {c}.", shape=sh) if o else None


def _mf_rect_eksik(subject):
    kind = random.choice(["alan", "cevre"])
    a, b = random.randint(4, 15), random.randint(2, 12)
    if a == b:
        return None
    A = a * b
    if kind == "alan":
        sh = {"type": "rectangle", "width": a, "height": b, "width_label": f"{a} cm", "height_label": "?", "center_label": f"Alan = {A} cm²"}
        c = b
        q = "Şekildeki dikdörtgenin alanı ve bir kenarının uzunluğu verilmiştir. Bu dikdörtgenin diğer kenarının uzunluğu kaç santimetredir?"
        ex = f"{A} ÷ {a} = {b}."
        wr = [a, A - a, a + b, A // 2 if A // 2 != b else A + 1, b + 1, b - 1]
    else:
        sh = {"type": "rectangle", "width": a, "height": b, "width_label": f"{a} cm", "height_label": f"{b} cm", "center_label": ""}
        c = 2 * (a + b)
        q = "Şekilde kenar uzunlukları verilen dikdörtgen biçimindeki bahçenin etrafı bir sıra tel ile çevrilecektir. Bunun için kaç santimetre tel gerekir?"
        ex = f"Çevre = 2 × ({a} + {b}) = {c} cm."
        wr = [a * b, a + b, c + 2, c - 2, 4 * a]
    o = _mf_opts(c, [w for w in wr if w > 0], str)
    return _mf_raw(subject, "Çevre ve alan", q, o, ex, shape=sh) if o else None


_mf_ang_tumler = _mk_kind(_mf_ang_tum, "tumler", "_mf_ang_tumler")
_mf_ang_butunler = _mk_kind(_mf_ang_tum, "butunler", "_mf_ang_butunler")
_mf_ang_tur = _mk_kind(_mf_ang_tum, "tur", "_mf_ang_tur")
_mf_ang_komsu = _mk_kind(_mf_ang_kom, False, "_mf_ang_komsu")
_mf_ang_ters = _mk_kind(_mf_ang_kom, True, "_mf_ang_ters")
_MF_GENS += [(_mf_ang_tumler, ("tümler",), (5,)), (_mf_ang_butunler, ("bütünler",), (5,)),
             (_mf_ang_tur, ("açı türleri", "açı ölçme", "açı ölç"), (5,)), (_mf_ang_komsu, ("komşu açı", "kesişen iki doğru"), (5,)),
             (_mf_ang_ters, ("ters", "karşıt", "kesişen iki doğru"), (5,)),
             (_mf_poly_el, ("çokgen",), (5,)), (_mf_rect_eksik, ("çevre", "alan", "dikdörtgen"), (5,))]


def _mf_tb_oran(subject, base=90):
    """Tümler/bütünler iki açıdan biri diğerinin k katı: küçük ya da büyük açıyı bulma (metin temelli, cebirsel akıl yürütme)."""
    k = random.choice([2, 3, 4, 5] if base == 180 else [2, 4, 5])
    if base % (k + 1):
        return None
    x = base // (k + 1)
    big = random.random() < .5
    c = k * x if big else x
    wr = [x if big else k * x, base - c + 10, c + 10, c - 10 if c > 10 else c + 20, base // 2]
    nm = "tümler" if base == 90 else "bütünler"
    o = _mf_opts(c, [w for w in wr if w > 0 and w != c], str)
    sh = {"type": "geo", "sub_type": "angle", "degree": base, "rotation": 0, "labels": ["O", "A", "B", "C"], "split": x, "split_labels": ["x", f"{k}x"], "angle_label": f"{base}°"}
    top = "dik açı olan AOB açısı" if base == 90 else "AOB doğru açısı"
    return _mf_raw(subject, "Açı ilişkileri", f"Şekildeki {top} OC ışınıyla iki açıya ayrılmıştır. Bu iki açıdan AOC açısının ölçüsü x, COB açısının ölçüsü {k}x ile gösterilmiştir. Buna göre {'COB' if big else 'AOC'} açısının ölçüsü kaç derecedir?", o,
                   f"x + {k}x = {base}° → x = {x}°; AOC = {x}°, COB = {k * x}°.", shape=sh) if o else None


_mf_tumler_oran = _mk_kind(lambda sj, kind=None: _mf_tb_oran(sj, 90), None, "_mf_tumler_oran")
_mf_butunler_oran = _mk_kind(lambda sj, kind=None: _mf_tb_oran(sj, 180), None, "_mf_butunler_oran")
_MF_GENS += [(_mf_tumler_oran, ("tümler",), (5,)), (_mf_butunler_oran, ("bütünler",), (5,))]
_DIFF_OF.update({"_mf_tumler_oran": 4, "_mf_butunler_oran": 4})


_EVRE = ["Yeni Ay", "İlk Dördün", "Dolunay", "Son Dördün"]


def _ff_yn_ay(subject):
    k = random.randrange(4)
    d0 = random.randint(1, 5)
    days = [d0 + 7 * i for i in range(3)]
    rows = [[f"{d}. gün", _EVRE[(k + i) % 4]] for i, d in enumerate(days)]
    shape = {"type": "table", "title": "Ay gözlem defteri", "headers": ["Gözlem günü", "Ay’ın evresi"], "rows": rows}
    lead = ("Ayşe, bir ay boyunca her akşam gökyüzünü gözlemliyor ve Ay’ın evresini defterine kaydediyor. Evreler yaklaşık 7 gün arayla aynı sırayla değişmektedir. "
            "Defterindeki ilk üç kayıt aşağıdaki tabloda verilmiştir.")
    j = random.choice([3, 4])
    day = d0 + 7 * j
    c = _EVRE[(k + j) % 4]
    q = f"Evrelerin değişim sırası aynı şekilde sürdüğüne göre Ayşe’nin {day}. gün gözlemleyeceği Ay evresi hangisidir?"
    o = _yn_opts(c, [e for e in _EVRE if e != c])
    ex = f"Evreler her 7 günde bir sırayla değişir: Yeni Ay → İlk Dördün → Dolunay → Son Dördün → Yeni Ay. {days[-1]}. günden sonra {j - 2} evre ilerlenir; {day}. günde Ay, {c} evresindedir."
    return _mf_raw(subject, "Ay’ın evreleri", q, o, ex, shape=shape, passage=lead) if o else None


_MIKRO = ["amip", "paramesyum", "öglena", "bakteri"]
_MAKRO = [("gül", "bitki"), ("çam ağacı", "bitki"), ("kedi", "hayvan"), ("serçe", "hayvan"), ("şapkalı mantar", "mantar"), ("kelebek", "hayvan"), ("lale", "bitki")]


def _ff_yn_mikro(subject):
    mk = random.choice(_MIKRO)
    mc = random.sample(_MAKRO, 3)
    lab = random.sample(["K", "L", "M", "N", "P", "R"], 4)
    items = [(mk, "Hayır", "Evet")] + [(n, "Evet", "Hayır") for n, _g in mc]
    random.shuffle(items)
    items = [(lab[i], a, b, c) for i, (a, b, c) in enumerate(items)]
    shape = {"type": "table", "title": "Gözlem sonuçları", "headers": ["Canlı", "Gözle görülebiliyor mu?", "Mikroskop gerekiyor mu?"], "rows": [[l, b, c] for l, _n, b, c in items]}
    lead = ("Bir öğrenci, harflerle adlandırdığı dört canlıyı önce çıplak gözle, sonra gerekiyorsa mikroskopla inceliyor. Canlılardan biri amip, paramesyum, öglena ya da bakteri gibi bir mikroskobik canlıdır; "
            "diğerleri gözle görülebilen canlılardır. Gözlem sonuçlarını tabloya kaydediyor.")
    q = "Tablodaki verilere göre hangi harfle gösterilen canlı mikroskobik canlıdır?"
    cor = [l for l, n, _b, _c in items if n == mk][0]
    o = _yn_opts(cor, [l for l in lab if l != cor])
    ex = f"Gözle görülemeyen ve incelenmesi için mikroskop gereken tek canlı {cor} harfiyle gösterilendir; bu nedenle mikroskobik canlıdır."
    return _mf_raw(subject, "Canlılar dünyası", q, o, ex, shape=shape, passage=lead) if o else None


_ff_yn_ay.ITEM = "Ay'ın evreleri"
_ff_yn_mikro.ITEM = "Mikroskobik canlılara (bakteri, amip, öglena, paramesyum) örnekler verme"
_FF_GENS += [(_ff_yn_ay, ("ay", "evre", "güneş")), (_ff_yn_mikro, ("mikroskobik", "canlı", "canlılar dünyası"))]
_DIFF_OF.update({"_ff_yn_ay": 3, "_ff_yn_mikro": 2})
_DIFF_OF.update({"_ff_yn_yay": 4, "_ff_yn_stop": 4, "_ff_yn_kaynama": 4, "_ff_yn_golge": 4, "_ff_yn_ampul": 4, "_ff_yn_yalitim": 4, "_ff_yn_atik": 3})


# ---- tümler / bütünler / komşu / ters açı: çok sayıda ayrı kalıp (her biri farklı soru kökü; anında üretilir)
def _split_shape(base, a, l1, l2):
    return {"type": "geo", "sub_type": "angle", "degree": base, "rotation": random.choice([0, 10]), "labels": ["O", "A", "B", "C"], "split": a, "split_labels": [l1, l2], "angle_label": f"{base}°"}


def _top_txt(base):
    return "dik açı olan AOB açısı" if base == 90 else "AOB doğru açısı"


def _mf_ab_x(subject, base=90):
    a = random.choice([v for v in range(10, base - 9, 5) if v * 2 != base])
    c = base - a
    sh = _split_shape(base, a, f"{a}°", "x")
    wr = [a, c + 10, c - 10, base + a, base - 2 * a if base - 2 * a > 0 else c + 20]
    o = _mf_opts(c, [w for w in wr if w > 0 and w != c], str)
    return _mf_raw(subject, "Açı ilişkileri", f"Şekildeki {_top_txt(base)} OC ışınıyla iki açıya ayrılmıştır. m(AOC) = {a}° ve m(COB) = x olduğuna göre x kaç derecedir?", o,
                   f"{a}° + x = {base}° olduğundan x = {base} − {a} = {c}°.", shape=sh) if o else None


def _mf_ab_cebir(subject, base=90):
    x = random.choice(range(15, 41 if base == 90 else 71, 5))
    k = base - 2 * x
    if k <= 0:
        return None
    sh = _split_shape(base, x, "x", f"x+{k}")
    wr = [x + 10, x - 10, k, base - x, x + 5]
    o = _mf_opts(x, [w for w in wr if w > 0 and w != x], str)
    return _mf_raw(subject, "Açı ilişkileri", f"Şekildeki {_top_txt(base)} OC ışınıyla iki açıya ayrılmıştır. m(AOC) = x ve m(COB) = x + {k}° olduğuna göre x kaç derecedir?", o,
                   f"x + (x + {k}) = {base}° → 2x = {base - k} → x = {x}°.", shape=sh) if o else None


def _mf_ab_cift(subject, base=90):
    nm = "tümler" if base == 90 else "bütünler"
    a = random.choice(range(15, base - 14, 5))
    c = base - a
    sh = {"type": "geo", "sub_type": "angle", "degree": a, "rotation": 0, "labels": ["O", "A", "B"], "angle_label": f"{a}°"}
    wr = [c + 10, c - 10 if c > 10 else c + 20, base + a if base + a < 200 else a + 5, a]
    o = _mf_opts(f"{c}°", [f"{w}°" for w in wr if w > 0 and w != c], str, sort=False)
    return _mf_raw(subject, "Açı ilişkileri", f"Şekilde ölçüsü verilen açı, aşağıdaki ölçülerden hangisiyle birlikte {nm} açı çifti oluşturur?", o,
                   f"{nm.capitalize()} açıların toplamı {base}° olur: {base} − {a} = {c}°.", shape=sh) if o and len(set(o[0])) == 4 else None


def _mf_kom_oran(subject):
    k = random.choice([2, 3, 4, 5])
    x = 180 // (k + 1)
    if x * (k + 1) != 180:
        return None
    sh = {"type": "geo", "sub_type": "angles_two_lines", "degree": k * x, "given": f"{k}x", "ask": "x"}
    o = _mf_opts(x, [k * x, x + 10, x - 10 if x > 10 else x + 20, 180 - x, 90 - x if 90 - x != x else x + 15], str)
    return _mf_raw(subject, "Açı ilişkileri", f"Şekilde kesişen iki doğrunun oluşturduğu komşu açılardan biri {k}x, diğeri x ile gösterilmiştir. Buna göre x kaç derecedir?", o,
                   f"Komşu açılar bütünlerdir: {k}x + x = 180° → x = {x}°.", shape=sh) if o else None


def _mf_kom_cebir(subject):
    x = random.randint(55, 68)
    a = random.randint(5, 30)
    b = 3 * x + a - 180
    d1, d2 = x + a, 2 * x - b
    if b <= 0 or d1 + d2 != 180 or d1 >= 175 or d2 <= 5 or d1 == 90:
        return None
    sh = {"type": "geo", "sub_type": "angles_two_lines", "degree": d1, "given": f"x+{a}", "ask": f"2x−{b}"}
    o = _mf_opts(x, [x + 5, x - 5, x + 10, d1, d2], str)
    return _mf_raw(subject, "Açı ilişkileri", f"Şekilde kesişen iki doğrunun oluşturduğu komşu açıların ölçüleri x + {a} ve 2x − {b} derecedir. Buna göre x kaçtır?", o,
                   f"Komşu açılar bütünlerdir: (x + {a}) + (2x − {b}) = 180 → 3x = {180 - a + b} → x = {x}.", shape=sh) if o else None


def _mf_ters_x(subject):
    d = random.choice([30, 40, 50, 55, 65, 70, 110, 120, 125, 130, 140])
    sh = {"type": "geo", "sub_type": "angles_two_lines", "degree": d, "given": f"{d}°", "ask": "x", "vertical": True}
    o = _mf_opts(d, [180 - d, 90 - d if d < 90 else d - 90, d + 10, d - 10, 360 - d], str)
    return _mf_raw(subject, "Açı ilişkileri", "Şekilde kesişen iki doğrunun oluşturduğu ters (karşıt) açılardan birinin ölçüsü verilmiştir. Buna göre x kaç derecedir?", o,
                   f"Ters açıların ölçüleri eşittir: x = {d}°.", shape=sh) if o else None


def _mf_ters_cebir(subject):
    x = random.randint(20, 40)
    a = random.randint(5, 15)
    k = x - a
    d = 2 * x + a
    if k <= 0 or d >= 175 or d == 90:
        return None
    sh = {"type": "geo", "sub_type": "angles_two_lines", "degree": d, "given": f"2x+{a}", "ask": f"3x−{k}", "vertical": True}
    o = _mf_opts(x, [x + 5, x - 5, d, x + 10, 180 - d], str)
    return _mf_raw(subject, "Açı ilişkileri", f"Şekilde kesişen iki doğrunun oluşturduğu ters açıların ölçüleri 2x + {a} ve 3x − {k} derecedir. Buna göre x kaçtır?", o,
                   f"Ters açılar eşittir: 2x + {a} = 3x − {k} → x = {x}.", shape=sh) if o else None


_mf_tum_x = _mk_kind(lambda sj, kind=None: _mf_ab_x(sj, 90), None, "_mf_tum_x")
_mf_but_x = _mk_kind(lambda sj, kind=None: _mf_ab_x(sj, 180), None, "_mf_but_x")
_mf_tum_cebir = _mk_kind(lambda sj, kind=None: _mf_ab_cebir(sj, 90), None, "_mf_tum_cebir")
_mf_but_cebir = _mk_kind(lambda sj, kind=None: _mf_ab_cebir(sj, 180), None, "_mf_but_cebir")
_mf_tum_cift = _mk_kind(lambda sj, kind=None: _mf_ab_cift(sj, 90), None, "_mf_tum_cift")
_mf_but_cift = _mk_kind(lambda sj, kind=None: _mf_ab_cift(sj, 180), None, "_mf_but_cift")
_TUM, _BUT, _KOM, _TER = ("tümler",), ("bütünler",), ("komşu açı", "kesişen iki doğru"), ("ters", "karşıt", "kesişen iki doğru")
_MF_GENS += [(_mf_tum_x, _TUM, (5,)), (_mf_tum_cebir, _TUM, (5,)), (_mf_tum_cift, _TUM, (5,)),
             (_mf_but_x, _BUT, (5,)), (_mf_but_cebir, _BUT, (5,)), (_mf_but_cift, _BUT, (5,)),
             (_mf_kom_oran, _KOM, (5,)), (_mf_kom_cebir, _KOM, (5,)), (_mf_ters_x, _TER, (5,)), (_mf_ters_cebir, _TER, (5,))]
_DIFF_OF.update({"_mf_tum_x": 2, "_mf_but_x": 2, "_mf_tum_cebir": 4, "_mf_but_cebir": 4, "_mf_tum_cift": 2, "_mf_but_cift": 2,
                 "_mf_kom_oran": 3, "_mf_kom_cebir": 5, "_mf_ters_x": 2, "_mf_ters_cebir": 5})


# ================================================================ 5. SINIF: TÜM ÜNİTELER İÇİN GENİŞ KALIP SETİ
def _stmt_q(subject, topic, stem, T, F, ex_t):
    """Tek doğru ifade: doğrulanmış doğru ifadelerden biri + yanlış ifadelerden üçü (olumlu kök)."""
    c = random.choice(T)
    return _fact_q(subject, topic, stem, c, random.sample(F, 3) if len(F) >= 3 else F, ex_t.format(c=c))


# ---------------------------------------------------------------- MATEMATİK
def _lset(subject, want):
    kinds = ["segment", "ray", "line"]
    random.shuffle(kinds)
    lab = ["I", "II", "III"]
    c = lab[kinds.index(want)]
    nm = {"segment": "doğru parçası", "ray": "ışın", "line": "doğru"}[want]
    sh = {"type": "geo", "sub_type": "lines_set", "kinds": kinds}
    o = _mf_opts(c, [x for x in lab if x != c] + ["Hiçbiri"], str, sort=False)
    q = {"segment": "Şekilde I., II. ve III. ile numaralandırılmış çizimlerden hangisi bir doğru parçasıdır?", "ray": "Şekilde I., II. ve III. ile numaralandırılmış çizimlerden hangisi bir ışındır?", "line": "Şekilde I., II. ve III. ile numaralandırılmış çizimlerden hangisi bir doğrudur?"}[want]
    return _mf_raw(subject, "Doğru, ışın, doğru parçası", q, o,
                   {"segment": "Doğru parçasının iki ucu da sınırlıdır.", "ray": "Işının bir başlangıç noktası vardır ve bir yönde sonsuza gider.", "line": "Doğru iki yönde de sonsuza uzanır."}[want], shape=sh) if o else None


_mf_lset_dogru = _mk_kind(lambda sj, kind=None: _lset(sj, "line"), None, "_mf_lset_dogru")
_mf_lset_isin = _mk_kind(lambda sj, kind=None: _lset(sj, "ray"), None, "_mf_lset_isin")
_mf_lset_parca = _mk_kind(lambda sj, kind=None: _lset(sj, "segment"), None, "_mf_lset_parca")


def _mf_dik_par(subject):
    par = random.random() < .5
    sh = {"type": "geo", "sub_type": "parallel" if par else "perpendicular", "labels": ["d₁", "d₂"], "tilt": random.choice([0, 15, 30])}
    c = "Paralel" if par else "Dik"
    o = _mf_opts(c, [x for x in ["Paralel", "Dik", "Çakışık", "Birbirine teğet"] if x != c], str, sort=False)
    return _mf_raw(subject, "Paralel ve dik doğrular", "Şekildeki d₁ ve d₂ doğrularının birbirine göre durumu aşağıdakilerden hangisidir?", o,
                   "Hiç kesişmeyen ve aralarındaki uzaklık değişmeyen doğrular paralel doğrulardır." if par else "Kesişince 90° açı oluşturan doğrular birbirine diktir.", shape=sh) if o else None


def _mf_aci_topla(subject):
    a, b = random.sample(range(15, 80, 5), 2)
    c = a + b
    sh = _split_shape(c, a, f"{a}°", f"{b}°")
    o = _mf_opts(c, [abs(a - b), c + 10, c - 10, a * 2, b * 2, c + 5], str)
    return _mf_raw(subject, "Açı ölçme", f"Şekilde OC ışını AOB açısını iki açıya ayırmıştır. m(AOC) = {a}° ve m(COB) = {b}° olduğuna göre m(AOB) kaç derecedir?", o, f"{a}° + {b}° = {c}°.", shape=sh) if o else None


def _mf_aortay_a(subject):
    a = random.choice(range(15, 80, 5))
    sh = _split_shape(2 * a, a, f"{a}°", "")
    o = _mf_opts(2 * a, [a, a + 10, 3 * a, 2 * a + 10, 2 * a - 10], str)
    return _mf_raw(subject, "Açıortay", f"Şekilde OC ışını AOB açısının açıortayıdır. m(AOC) = {a}° olduğuna göre m(AOB) kaç derecedir?", o, f"Açıortay açıyı iki eşit parçaya böler: 2 × {a}° = {2 * a}°.", shape=sh) if o else None


def _mf_aortay_cebir(subject):
    x = random.randint(8, 25)
    a, b = random.randint(5, 20), random.randint(1, 15)
    # 2x + a = 3x - b  -> x = a + b  ; seç: x = a + b
    x = a + b
    d = 2 * x + a
    if d * 2 >= 180 or d < 20:
        return None
    sh = _split_shape(2 * d, d, f"2x+{a}", f"3x−{b}")
    o = _mf_opts(x, [x + 5, x - 5, d, x + 10, 2 * d], str)
    return _mf_raw(subject, "Açıortay", f"Şekilde OC ışını AOB açısının açıortayıdır. m(AOC) = 2x + {a}° ve m(COB) = 3x − {b}° olduğuna göre x kaçtır?", o,
                   f"Açıortay açıyı eşit böler: 2x + {a} = 3x − {b} → x = {x}.", shape=sh) if o else None


def _mf_cember_cap(subject):
    r = random.randint(2, 15)
    kind = random.choice(["cap", "yarim"])
    sh = {"type": "circle", "center": "O", "radius": f"{r} cm", "show_diameter": True}
    if kind == "cap":
        c = 2 * r
        o = _mf_opts(c, [r, r + 2, 2 * r + 2, 3 * r, r * r], str)
        return _mf_raw(subject, "Çember ve daire elemanları", f"Şekildeki O merkezli çemberin yarıçapı {r} cm’dir. Bu çemberin çapı kaç santimetredir?", o, f"Çap, yarıçapın 2 katıdır: 2 × {r} = {c} cm.", shape=sh) if o else None
    c = r
    o = _mf_opts(c, [2 * r, r + 1, r - 1 if r > 2 else r + 3, 4 * r], str)
    return _mf_raw(subject, "Çember ve daire elemanları", f"Şekildeki O merkezli çemberin yarıçapı {r} cm’dir. Çemberin merkezinden geçen bir kirişin yarısının uzunluğu kaç santimetredir?", o, f"Merkezden geçen kiriş çaptır; yarısı yarıçaptır: {r} cm.", shape=sh) if o else None


def _mf_cember_ad(subject):
    sh = {"type": "geo", "sub_type": "circle_parts", "center": "O", "parts": ["radius", "diameter", "chord"], "labels": ["A", "B", "C", "D", "E"]}
    seg, c, ex = random.choice([("OA", "Yarıçap", "Merkezi ile çember üzerindeki bir noktayı birleştiren doğru parçası yarıçaptır."),
                                ("BC", "Çap", "Merkezden geçen ve çember üzerinde iki noktayı birleştiren doğru parçası çaptır."),
                                ("DE", "Kiriş", "Merkezden geçmeyen, çember üzerinde iki noktayı birleştiren doğru parçası kiriştir.")])
    o = _mf_opts(c, [x for x in ["Çap", "Yarıçap", "Kiriş", "Yay"] if x != c], str, sort=False)
    return _mf_raw(subject, "Çember ve daire elemanları", f"Şekildeki O merkezli çemberde gösterilen {seg} doğru parçasına ne ad verilir?", o, ex, shape=sh) if o else None


def _mf_poly_set(subject):
    nm = {3: "üçgen", 4: "dörtgen", 5: "beşgen", 6: "altıgen"}
    ks = random.sample(list(nm), 4)
    want = random.choice(ks)
    lab = ["K", "L", "M", "N"]
    sh = {"type": "geo", "sub_type": "polygon_set", "kinds": [nm[k] for k in ks], "labels": lab}
    c = lab[ks.index(want)]
    return _mf_raw(subject, "Çokgenlerin elemanları", f"Şekilde K, L, M ve N ile gösterilen çokgenlerden hangisinin {want} kenarı vardır?",
                   (sorted(lab), c), f"{nm[want].capitalize()}in {want} kenarı vardır; şekilde bu çokgen {c} harfiyle gösterilmiştir.", shape=sh)


def _mf_kare(subject):
    a = random.randint(3, 15)
    kind = random.choice(["cevre", "alan", "kenar"])
    if kind == "kenar":
        sh = {"type": "rectangle", "width": a, "height": a, "width_label": "?", "height_label": "?", "center_label": f"Çevre = {4 * a} cm"}
        o = _mf_opts(a, [4 * a, a + 2, a * a, 2 * a, a - 1], str)
        return _mf_raw(subject, "Çevre uzunluğu", "Şekilde çevresi verilen karenin bir kenarı kaç santimetredir?", o, f"Kare 4 eşit kenarlıdır: {4 * a} ÷ 4 = {a}.", shape=sh) if o else None
    sh = {"type": "rectangle", "width": a, "height": a, "width_label": f"{a} cm", "height_label": f"{a} cm"}
    if kind == "cevre":
        o = _mf_opts(4 * a, [a * a, 2 * a, a + 4, 4 * a + 4], str)
        return _mf_raw(subject, "Çevre uzunluğu", "Şekildeki karenin çevresi kaç santimetredir?", o, f"4 × {a} = {4 * a} cm.", shape=sh) if o else None
    o = _mf_opts(a * a, [4 * a, 2 * a, a * a + a, a * a - a], str)
    return _mf_raw(subject, "Alan ölçme", "Şekildeki karenin alanı kaç santimetrekaredir?", o, f"{a} × {a} = {a * a} cm².", shape=sh) if o else None


def _mf_say_kars(subject):
    ns = random.sample(range(100000, 9999999), 4)
    big = random.random() < .5
    c = max(ns) if big else min(ns)
    f = lambda v: f"{v:,}".replace(",", ".")
    if len({len(str(n)) for n in ns}) < 2 and len(set(str(n)[:3] for n in ns)) < 4:
        return None
    o = _mf_opts(f(c), [f(n) for n in ns if n != c], str, sort=False)
    return _mf_raw(subject, "Doğal sayılar", f"Aşağıdaki sayılardan hangisi en {'büyüktür' if big else 'küçüktür'}?", o, f"Basamak sayısı çok olan ve en yüksek basamağı büyük olan sayı daha büyüktür; en {'büyük' if big else 'küçük'} sayı {f(c)}.") if o else None


def _mf_prb_gun(subject):
    pg, k = random.choice([120, 150, 180, 240, 300, 360, 420]), random.choice([5, 6, 10, 12, 15, 20, 30])
    if pg % k:
        return None
    c = pg // k
    o = _mf_opts(c, [pg - k, c + 2, c - 2, pg + k, c * 2], str)
    nm = random.choice(["Elif", "Mert", "Ali"])
    return _mf_raw(subject, "Dört işlem problemleri", f"{nm} {pg} sayfalık bir kitabı her gün {k} sayfa okuyarak bitirecektir. {nm} kitabı kaç günde bitirir?", o, f"{pg} ÷ {k} = {c} gün.") if o else None


def _mf_prb_arac(subject):
    k, c = random.choice([4, 5, 8, 9, 12]), random.randint(3, 9)
    n = k * (c - 1) + random.randint(1, k - 1)
    o = _mf_opts(c, [c - 1, c + 1, c + 2, n // k + 2], str)
    return _mf_raw(subject, "Dört işlem problemleri", f"Bir okuldan {n} öğrenci gezi için servislere bindirilecektir. Her servise en fazla {k} öğrenci binebildiğine göre en az kaç servis gerekir?", o,
                   f"{n} ÷ {k} = {n // k} kalan {n % k}; kalan öğrenciler için bir servis daha gerekir: {c}.") if o and len(set(o[0])) == 4 else None


def _mf_prb_alis(subject):
    a, b, p = random.randint(12, 60), random.randint(8, 40), random.randint(2, 9)
    tot = a * p + b * p
    o = _mf_opts(tot, [a * p + b, a + b * p, (a + b) + p, tot + p, tot - p], str)
    return _mf_raw(subject, "Dört işlem problemleri", f"Bir kırtasiyede defterin tanesi {a} TL, kalemin tanesi {b} TL’dir. Zeynep {p} defter ve {p} kalem aldığına göre kaç TL öder?", o, f"({a} + {b}) × {p} = {tot} TL.") if o else None


def _mf_orun_kural(subject):
    a, d = random.randint(2, 9), random.randint(2, 7)
    n = random.choice([8, 10, 12, 15])
    t = [a + d * i for i in range(3)]
    c = a + d * (n - 1)
    o = _mf_opts(c, [c + d, c - d, a + d * n + 1, n * d, c + 1], str)
    return _mf_raw(subject, "Örüntüler", f"Bir sayı örüntüsünün ilk üç terimi {t[0]}, {t[1]}, {t[2]} biçimindedir ve örüntü aynı kuralla devam etmektedir. Bu örüntünün {n}. terimi kaçtır?", o,
                   f"Her adımda {d} artıyor: {a} + {n - 1} × {d} = {c}.") if o else None


