             (_df_kuran, ("kur'an", "kur’an", "kevser", "sure")), (_df_kuran2, ("kur'an", "kur’an")), (_df_kissa, ("kıssa", "peygamber")), (_df_kissa2, ("kıssa", "peygamber")), (_df_kissa3, ("kıssa", "peygamber")),
