# ================================================================ 5. SINIF — LGS TARZI ÖNCÜLLÜ (I-II-III) SORULAR + YENİ BİLGİ HAVUZLARI + MATEMATİK EK KALIPLAR
def _tfpool(topic, T, F, S, name, reg, kw, d=2, fn=_fen_stmt):
    g = fn(topic, T, F, S)
    g.__name__ = name
    reg.append((g, kw))
    _DIFF_OF[name] = d
    return g


