    c = random.choice(S[s])
    wr = [m for k, v in S.items() if k != s for m in v]
    return _en_q("Seasons", f"Which month is in {s} in Turkey?", c, random.sample(wr, 3), f"{c} ayı {s} mevsimindedir.")


