                        st.caption(f"🧠 Yapay zekâ ile doğrulanan bilgi: {sum(1 for v in _bv.values() if v == 'ok')} • reddedilen (devre dışı): {len(_bsu)}")
                        if st.button("Bilgi bankasını yapay zekâyla doğrula (bir tur)", key="run_vbank"):
                            from core import ai_engine as _vai
